import json, re, datetime, pathlib
ROOT = pathlib.Path("/Users/billyribeiro/.fanout/wt/verifyB12-M4-d")
S = "ledgers/M4/scripts/M4-d-r12/"
mut_lines = (ROOT / S / "mutate_M4_r12.out").read_text(encoding="utf-8").splitlines()
mutants = []
for ln in mut_lines:
    m = re.match(r"^(KILLED|SURVIVED) (\S+): (.*?) -> (.*)$", ln)
    if not m:
        continue
    status, name, desc, killer = m.groups()
    killed_by = None if killer.strip() == "None" else killer.strip()
    if status == "SURVIVED":
        killed_by = None
        desc = desc + " [ACCEPTED SURVIVOR: " + {
            "m11_loss_sign_flipped.py": "project.html:228 states the suite does not test the loss sign",
            "m17_student_t_second_seed.py": "no stated behaviour: project.html:215 says the stream order is not fixed; not a page-stated violation",
            "r9_03_student_t_chi_square_reused_every_second_draw.py": "project.html:228 states the suite does not check one chi-square per draw (seeds 0 to 9)",
            "v4_m02_matched_factor_skipped_for_small_nu.py": "project.html:228 states the matched factor at nu 3 and 4 is not checked",
        }[name] + "]"
    mutants.append({"name": name, "description": desc, "killed_by": killed_by, "status": status})

def R(id_, check, location, status, evidence, fix=None):
    r = {"id": id_, "check": check, "location": location, "status": status, "evidence": evidence}
    if status != "PASS":
        r["fix"] = fix
    return r

